// Input not mutated
const b = ['x', 'y', 'x'];
const before = JSON.stringify(b);
uniqueStrings(b);
console.assert(JSON.stringify(b) === before, 'mutation detected');

// Empty array
console.log('empty:', JSON.stringify(uniqueStrings([])));

// Single element
console.log('single:', JSON.stringify(uniqueStrings(['only'])));

